func (fx *MetadataServiceArtifactTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *MetadataServiceArtifactTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *MetadataServiceArtifactTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *MetadataServiceArtifactTestSuiteConfig) normalize(msg *Artifact) *Artifact {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*Artifact)
	fx.Normalize(normalized)
	return normalized
}

func (fx *MetadataServiceArtifactTestSuiteConfig) normalizeAll(msgs []*Artifact) []*Artifact {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*Artifact, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *MetadataServiceArtifactTestSuiteConfig) listed(t *testing.T, parent string, want, got []*Artifact) []*Artifact {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.Name] = true
	}
	created := make([]*Artifact, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.Name, parent+"/"), "listed resource is not under the parent")
		if names[msg.Name] {
			created = append(created, msg)
		}
	}
	return created
}

func (fx *MetadataServiceArtifactTestSuiteConfig) create(t *testing.T, parent string) *Artifact {
	t.Helper()
	created, err := fx.Service().CreateArtifact(fx.Context(), &CreateArtifactRequest{
		Parent:   parent,
		Artifact: fx.Create(parent),
	})
	assert.NilError(t, err)
	return created
}

func (fx *MetadataServiceArtifactTestSuiteConfig) notFoundName(name string) string {
	// appending to the resource name ensures it is valid
	return name + "notfound"
}

func (fx *MetadataServiceArtifactTestSuiteConfig) field(msg *Artifact, name protoreflect.Name) *Artifact {
	msg = fx.normalize(msg)
	fd := msg.ProtoReflect().Descriptor().Fields().ByName(name)
	only := &Artifact{}
	if msg.ProtoReflect().Has(fd) {
		only.ProtoReflect().Set(fd, msg.ProtoReflect().Get(fd))
	}
	return only
}

func (fx *MetadataServiceArtifactTestSuiteConfig) withoutField(msg *Artifact, name protoreflect.Name) *Artifact {
	cleared := proto.Clone(msg).(*Artifact)
	cleared.ProtoReflect().Clear(cleared.ProtoReflect().Descriptor().Fields().ByName(name))
	return cleared
}

type MetadataServiceContextTestSuiteConfig struct {
	currParent int

	// Service should return the service that should be tested.
	// The service will be used for several tests.
	Service func() MetadataServiceServer
	// Context should return a new context.
	// The context will be used for several tests.
	Context func() context.Context
	// The parents to use when creating resources.
	// At least one parent needs to be set. Depending on methods available on the resource,
	// more may be required. If insufficient number of parents are
	// provided the test will fail.
	Parents []string
	// Preexisting is the number of resources each parent has before the tests create any,
	// such as ones the service creates together with the parent. The List and Search tests
	// expect that many resources under the parent besides the ones they create.
	Preexisting int
	// Create should return a resource which is valid to create, i.e.
	// all required fields set.
	Create func(parent string) *Context
	// Update should return a resource which is valid to update, i.e.
	// all required fields set.
	// The tests of update masks compare each field that Update can change with the
	// value it had after Create, so they find most when Create and Update set each
	// such field, to different values.
	Update func(parent string) *Context
	// Normalize, if non-nil, changes a copy of each resource before a test compares it
	// with another, such as to clear a field that the service returns from one method only.
	// Clear only fields that differ between calls by design: what Normalize clears, no
	// test compares.
	Normalize func(*Context)
	// Patterns of tests to skip.
	// For example if a service has a Get method:
	// Skip: ["Get"] will skip all tests for Get.
	// Skip: ["Get/persisted"] will only skip the subtest called "persisted" of Get.
	Skip []string
}

func (fx *MetadataServiceContextTestSuiteConfig) test(t *testing.T) {
	t.Run("Create", fx.testCreate)
	t.Run("Get", fx.testGet)
	t.Run("Update", fx.testUpdate)
	t.Run("List", fx.testList)
	t.Run("Delete", fx.testDelete)
}

func (fx *MetadataServiceContextTestSuiteConfig) testCreate(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if no parent is provided.
	t.Run("missing parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().CreateContext(fx.Context(), &CreateContextRequest{
			Parent:  "",
			Context: fx.Create(fx.nextParent(t, false)),
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument if provided parent is invalid.
	t.Run("invalid parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().CreateContext(fx.Context(), &CreateContextRequest{
			Parent:  "invalid resource name",
			Context: fx.Create(fx.nextParent(t, false)),
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Field create_time should be populated when the resource is created.
	t.Run("create time", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		// allow for the clock of the service to run up to a second behind the clock of the test
		beforeCreate := time.Now().Add(-time.Second)
		msg, err := fx.Service().CreateContext(fx.Context(), &CreateContextRequest{
			Parent:  parent,
			Context: fx.Create(parent),
		})
		assert.NilError(t, err)
		assert.Check(t, msg.CreateTime != nil)
		assert.Check(t, !msg.CreateTime.AsTime().IsZero())
		assert.Check(t, msg.CreateTime.AsTime().After(beforeCreate), "msg.CreateTime (%v) is not after beforeCreate (%v)", msg.CreateTime.AsTime(), beforeCreate)
	})

	// The created resource should be persisted and reachable with Get.
	t.Run("persisted", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		msg, err := fx.Service().CreateContext(fx.Context(), &CreateContextRequest{
			Parent:  parent,
			Context: fx.Create(parent),
		})
		assert.NilError(t, err)
		persisted, err := fx.Service().GetContext(fx.Context(), &GetContextRequest{
			Name: msg.Name,
		})
		assert.NilError(t, err)
		assert.DeepEqual(t, fx.normalize(msg), fx.normalize(persisted), protocmp.Transform())
	})

	// Field etag should be populated when the resource is created.
	t.Run("etag populated", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created, err := fx.Service().CreateContext(fx.Context(), &CreateContextRequest{
			Parent:  parent,
			Context: fx.Create(parent),
		})
		assert.NilError(t, err)
		assert.Check(t, created.Etag != "")
	})

}

