func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) testList(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if provided parent is invalid.
	t.Run("invalid parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
			Parent: "invalid resource name",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument is provided page token is not valid.
	t.Run("invalid page token", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
			Parent:    parent,
			PageToken: "invalid page token",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument is provided page size is negative.
	t.Run("negative page size", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
			Parent:   parent,
			PageSize: -10,
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	{
		const resourcesCount = 5
		parent := fx.nextParent(t, true)
		parentMsgs := make([]*MetadataSchema, resourcesCount)
		for i := 0; i < resourcesCount; i++ {
			parentMsgs[i] = fx.create(t, parent)
		}

		// If parent is provided the method must only return resources
		// under that parent.
		t.Run("isolation", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
				Parent:   parent,
				PageSize: 999,
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				fx.normalizeAll(parentMsgs),
				fx.normalizeAll(fx.listed(t, parent, parentMsgs, response.MetadataSchemas)),
				cmpopts.SortSlices(func(a, b *MetadataSchema) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// If there are no more resources, next_page_token should not be set.
		t.Run("last page", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
				Parent:   parent,
				PageSize: int32(resourcesCount + fx.Preexisting),
			})
			assert.NilError(t, err)
			assert.Equal(t, "", response.NextPageToken)
		})

		// If there are more resources, next_page_token should be set.
		t.Run("more pages", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
				Parent:   parent,
				PageSize: resourcesCount - 1,
			})
			assert.NilError(t, err)
			assert.Check(t, response.NextPageToken != "")
		})

		// Listing resource one by one should eventually return all resources.
		t.Run("one by one", func(t *testing.T) {
			fx.maybeSkip(t)
			msgs := make([]*MetadataSchema, 0, resourcesCount)
			var nextPageToken string
			for {
				response, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
					Parent:    parent,
					PageSize:  1,
					PageToken: nextPageToken,
				})
				assert.NilError(t, err)
				assert.Equal(t, 1, len(response.MetadataSchemas))
				msgs = append(msgs, response.MetadataSchemas...)
				nextPageToken = response.NextPageToken
				if nextPageToken == "" {
					break
				}
			}
			assert.DeepEqual(
				t,
				fx.normalizeAll(parentMsgs),
				fx.normalizeAll(fx.listed(t, parent, parentMsgs, msgs)),
				cmpopts.SortSlices(func(a, b *MetadataSchema) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// When listing resource with page size zero the service should use a default value.
		t.Run("page size zero", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListMetadataSchemas(fx.Context(), &ListMetadataSchemasRequest{
				Parent:   parent,
				PageSize: 0,
			})
			assert.NilError(t, err)
			// Server should use a default page size and return at least some results
			assert.Check(t, len(response.MetadataSchemas) > 0, "expected server to return at least 1 resource with page_size=0")
		})

	}
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) normalize(msg *MetadataSchema) *MetadataSchema {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*MetadataSchema)
	fx.Normalize(normalized)
	return normalized
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) normalizeAll(msgs []*MetadataSchema) []*MetadataSchema {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*MetadataSchema, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) listed(t *testing.T, parent string, want, got []*MetadataSchema) []*MetadataSchema {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.Name] = true
	}
	created := make([]*MetadataSchema, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.Name, parent+"/"), "listed resource is not under the parent")
		if names[msg.Name] {
			created = append(created, msg)
		}
	}
	return created
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) create(t *testing.T, parent string) *MetadataSchema {
	t.Helper()
	created, err := fx.Service().CreateMetadataSchema(fx.Context(), &CreateMetadataSchemaRequest{
		Parent:         parent,
		MetadataSchema: fx.Create(parent),
	})
	assert.NilError(t, err)
	return created
}

func (fx *MetadataServiceMetadataSchemaTestSuiteConfig) notFoundName(name string) string {
	// appending to the resource name ensures it is valid
	return name + "notfound"
}

type MetadataServiceMetadataStoreTestSuiteConfig struct {
	currParent int

	// Service should return the service that should be tested.
	// The service will be used for several tests.
	Service func() MetadataServiceServer
	// Context should return a new context.
	// The context will be used for several tests.
	Context func() context.Context
	// The parents to use when creating resources.
	// At least one parent needs to be set. Depending on methods available on the resource,
	// more may be required. If insufficient number of parents are
	// provided the test will fail.
	Parents []string
	// Preexisting is the number of resources each parent has before the tests create any,
	// such as ones the service creates together with the parent. The List and Search tests
	// expect that many resources under the parent besides the ones they create.
	Preexisting int
	// Create should return a resource which is valid to create, i.e.
	// all required fields set.
	Create func(parent string) *MetadataStore
	// Normalize, if non-nil, changes a copy of each resource before a test compares it
	// with another, such as to clear a field that the service returns from one method only.
	// Clear only fields that differ between calls by design: what Normalize clears, no
	// test compares.
	Normalize func(*MetadataStore)
	// Patterns of tests to skip.
	// For example if a service has a Get method:
	// Skip: ["Get"] will skip all tests for Get.
	// Skip: ["Get/persisted"] will only skip the subtest called "persisted" of Get.
	Skip []string
}

