func (fx *MetadataServiceMetadataStoreTestSuiteConfig) testDelete(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if no name is provided.
	t.Run("missing name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteMetadataStore(fx.Context(), &DeleteMetadataStoreRequest{
			Name: "",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument if the provided name is not valid.
	t.Run("invalid name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteMetadataStore(fx.Context(), &DeleteMetadataStoreRequest{
			Name: "invalid resource name",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Resource should be deleted without errors if it exists.
	t.Run("exists", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteMetadataStore(fx.Context(), &DeleteMetadataStoreRequest{
			Name: created.Name,
		})
		assert.NilError(t, err)
	})

	// Method should fail with NotFound if the resource does not exist.
	t.Run("not found", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteMetadataStore(fx.Context(), &DeleteMetadataStoreRequest{
			Name: fx.notFoundName(created.Name),
		})
		assert.Equal(t, codes.NotFound, status.Code(err), err)
	})

	// Method should fail with InvalidArgument if the provided name only contains wildcards ('-')
	t.Run("only wildcards", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteMetadataStore(fx.Context(), &DeleteMetadataStoreRequest{
			Name: "projects/-/locations/-/metadataStores/-",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) normalize(msg *MetadataStore) *MetadataStore {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*MetadataStore)
	fx.Normalize(normalized)
	return normalized
}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) normalizeAll(msgs []*MetadataStore) []*MetadataStore {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*MetadataStore, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *MetadataServiceMetadataStoreTestSuiteConfig) listed(t *testing.T, parent string, want, got []*MetadataStore) []*MetadataStore {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.Name] = true
	}
	created := make([]*MetadataStore, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.Name, parent+"/"), "listed resource is not under the parent")
		if names[msg.Name] {
			created = append(created, msg)
		}
	}
	return created
}

